16	    /// Compile `schema`. Fails with [`EvalError::InvalidSchema`] if the
17	    /// schema itself is invalid.
18	    pub fn new(schema: Value) -> Result<Self, EvalError> {
19	        let validator = jsonschema::validator_for(&schema)
