26	impl Evaluator for JsonSchemaConformance {
27	    fn name(&self) -> &str {
28	        "json_schema"
29	    }
30	
31	    async fn evaluate(&self, _case: &EvalCase, outcome: &CaseOutcome) -> Result<Score, EvalError> {
32	        let value: Value = match serde_json::from_str(outcome.final_output.trim()) {
33	            Ok(v) => v,
34	            Err(e) => {
35	                return Ok(Score::failed(
